function wpbp_abilities_api_011( string $category ): array {
	if ( ! function_exists( 'wp_get_abilities' ) ) {
		return array();
	}

	$abilities = wp_get_abilities();
	if ( ! is_array( $abilities ) ) {
		return array();
	}

	$names = array();

	foreach ( $abilities as $key => $ability ) {
		if ( is_object( $ability ) && method_exists( $ability, 'get_category' ) ) {
			if ( (string) $ability->get_category() !== $category ) {
				continue;
			}
			$names[] = method_exists( $ability, 'get_name' ) ? (string) $ability->get_name() : (string) $key;
		}
	}

	$names = array_values( array_unique( $names ) );
	sort( $names, SORT_STRING );

	return $names;
}
