	 */
	function wpbp_abilities_api_012( string $ability_name ): array {
		$result = array(
			'registered'   => false,
			'show_in_rest' => false,
		);

		if ( ! function_exists( 'wp_has_ability' ) || ! function_exists( 'wp_get_ability' ) ) {
			return $result;
		}

		// Gate with wp_has_ability() so unknown names never trigger a registry notice.
		if ( ! wp_has_ability( $ability_name ) ) {
			return $result;
		}

		$ability = wp_get_ability( $ability_name );

		if ( ! $ability ) {
			return $result;
		}

		$result['registered'] = true;

		$meta = $ability->get_meta();

		if ( is_array( $meta ) && isset( $meta['show_in_rest'] ) ) {
			$result['show_in_rest'] = (bool) $meta['show_in_rest'];
		}

		return $result;
	}
}
