if ( ! function_exists( 'wpbp_sanitize_retention_days' ) ) {
	/**
	 * Validate the retention days setting.
	 *
	 * @param mixed $value Submitted value.
	 * @return int Valid new value, or the previously stored value.
	 */
	function wpbp_sanitize_retention_days( $value ) {
		if ( is_string( $value ) ) {
			$value = trim( $value );
		}

		$validated = false;

		if ( is_int( $value ) || is_string( $value ) ) {
			$validated = filter_var(
				$value,
				FILTER_VALIDATE_INT,
				array(
					'options' => array(
						'min_range' => 1,
						'max_range' => 90,
					),
				)
			);
		}

		if ( false === $validated ) {
			add_settings_error(
				'wpbp_retention_days',
				'wpbp_retention_invalid',
				__( 'Retention days must be a whole number from 1 to 90.', 'wpbp' ),
				'error'
			);

			return (int) get_option( 'wpbp_retention_days', 30 );
		}

		return (int) $validated;
	}
}

if ( ! function_exists( 'wpbp_register_retention_setting' ) ) {
	function wpbp_register_retention_setting() {
		register_setting(
