if ( ! function_exists( 'wpbp_toggle_featured_handler' ) ) {
	function wpbp_toggle_featured_handler() {
		// Verify nonce from the standard _ajax_nonce field; die with 403 on failure.
		check_ajax_referer( 'wpbp_toggle', '_ajax_nonce' );

		$post_id = isset( $_POST['post_id'] ) ? absint( wp_unslash( $_POST['post_id'] ) ) : 0;

		if ( ! $post_id || ! get_post( $post_id ) ) {
			wp_send_json_error( array( 'message' => 'Invalid post.' ), 400 );
		}

		if ( ! current_user_can( 'edit_post', $post_id ) ) {
			wp_send_json_error( array( 'message' => 'Forbidden.' ), 403 );
		}

		$current = get_post_meta( $post_id, 'wpbp_featured', true );
		$new     = ( 'on' === $current ) ? 'off' : 'on';

		update_post_meta( $post_id, 'wpbp_featured', $new );

		wp_send_json_success( array( 'featured' => $new ) );
	}
}

// Signed-in users only: register only the wp_ajax_ hook (no nopriv).
add_action( 'wp_ajax_wpbp_toggle_featured', 'wpbp_toggle_featured_handler' );
