	function wpbp_isbn_render_meta_box( $post ) {
		$value = get_post_meta( $post->ID, '_wpbp_isbn', true );
		if ( ! is_string( $value ) ) {
			$value = '';
		}

		wp_nonce_field( 'wpbp_isbn_save', 'wpbp_isbn_nonce' );
		?>
		<label class="screen-reader-text" for="wpbp_isbn"><?php echo esc_html( 'ISBN' ); ?></label>
		<input type="text" id="wpbp_isbn" name="wpbp_isbn" value="<?php echo esc_attr( $value ); ?>" class="widefat" />
		<?php
	}
}

if ( ! function_exists( 'wpbp_isbn_save_post' ) ) {
	function wpbp_isbn_save_post( $post_id, $post = null ) {
		$post_id = (int) $post_id;

		if ( wp_is_post_revision( $post_id ) ) {
			return;
		}

		if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) {
			return;
		}

		if ( 'wpbp_book' !== get_post_type( $post_id ) ) {
			return;
		}

		if ( ! isset( $_POST['wpbp_isbn_nonce'] ) || ! is_string( $_POST['wpbp_isbn_nonce'] ) ) {
			return;
		}

		$nonce = sanitize_text_field( wp_unslash( $_POST['wpbp_isbn_nonce'] ) );
		if ( ! wp_verify_nonce( $nonce, 'wpbp_isbn_save' ) ) {
			return;
		}

		if ( ! current_user_can( 'edit_post', $post_id ) ) {
			return;
		}

		if ( ! isset( $_POST['wpbp_isbn'] ) || ! is_string( $_POST['wpbp_isbn'] ) ) {
			return;
		}

		$isbn = trim( wp_strip_all_tags( wp_unslash( $_POST['wpbp_isbn'] ) ) );

		update_post_meta( $post_id, '_wpbp_isbn', $isbn );
	}
}

