<?php
/**
 * Add an "Archive" bulk action to the wpbp_book list table.
 */

// Register the bulk action alongside the existing ones.
add_filter( 'bulk_actions-edit-wpbp_book', 'wpbp_register_archive_bulk_action' );

function wpbp_register_archive_bulk_action( $bulk_actions ) {
	$bulk_actions['wpbp_archive'] = __( 'Archive', 'wpbp' );
	return $bulk_actions;
}

// Handle the bulk action.
add_filter( 'handle_bulk_actions-edit-wpbp_book', 'wpbp_handle_archive_bulk_action', 10, 3 );

function wpbp_handle_archive_bulk_action( $redirect_url, $action, $post_ids ) {
	if ( 'wpbp_archive' !== $action ) {
		return $redirect_url;
	}

	$archived = 0;

	if ( is_array( $post_ids ) ) {
		foreach ( $post_ids as $post_id ) {
			$post_id = absint( $post_id );

			if ( ! $post_id ) {
				continue;
			}

			if ( 'wpbp_book' !== get_post_type( $post_id ) ) {
				continue;
			}

			if ( ! current_user_can( 'edit_post', $post_id ) ) {
				continue;
			}

			update_post_meta( $post_id, 'wpbp_archived', 1 );
			$archived++;
		}
	}

	return add_query_arg( 'wpbp_archived', $archived, $redirect_url );
}
