<?php
/**
 * Handle the wpbp_save_note admin form submission (signed-in users only).
 */
function wpbp_handle_save_note() {
	$nonce = isset( $_POST['wpbp_note_nonce'] ) && is_string( $_POST['wpbp_note_nonce'] )
		? sanitize_text_field( wp_unslash( $_POST['wpbp_note_nonce'] ) )
		: '';

	if ( '' === $nonce || ! wp_verify_nonce( $nonce, 'wpbp_save_note' ) ) {
		wp_die(
			esc_html__( 'Security check failed.', 'wpbp' ),
			esc_html__( 'Error', 'wpbp' ),
			array( 'response' => 403 )
		);
	}

	if ( ! current_user_can( 'manage_options' ) ) {
		wp_die(
			esc_html__( 'You do not have permission to do this.', 'wpbp' ),
			esc_html__( 'Error', 'wpbp' ),
			array( 'response' => 403 )
		);
	}

	$note = '';
	if ( isset( $_POST['wpbp_note'] ) && is_string( $_POST['wpbp_note'] ) ) {
		// Remove the slashes PHP/WordPress adds to posted data, then strip markup and newlines.
		$note = sanitize_text_field( wp_unslash( $_POST['wpbp_note'] ) );
	}

	update_option( 'wpbp_note', $note );

	wp_safe_redirect( add_query_arg( 'wpbp_saved', '1', admin_url( 'options-general.php' ) ) );
	exit;
}

// Signed-in users only: register the admin_post_ hook, not admin_post_nopriv_.
add_action( 'admin_post_wpbp_save_note', 'wpbp_handle_save_note' );
