if ( ! function_exists( 'wpbp_get_backup_freshness_result' ) ) {
	/**
	 * Direct Site Health test callback.
	 *
	 * @return array
	 */
	function wpbp_get_backup_freshness_result() {
		$last_backup = get_option( 'wpbp_last_backup', 0 );
		$now         = time();
		$week        = 7 * DAY_IN_SECONDS;

		$has_backup = is_numeric( $last_backup ) && (int) $last_backup > 0;
		$timestamp  = $has_backup ? (int) $last_backup : 0;
		$is_fresh   = $has_backup && $timestamp <= $now + 300 && ( $now - $timestamp ) < $week;

		$result = array(
			'label'       => '',
			'status'      => '',
			'badge'       => array(
				'label' => __( 'Backups', 'wpbp' ),
				'color' => 'blue',
			),
			'description' => '',
			'actions'     => '',
			'test'        => 'wpbp_backup_freshness',
		);

		if ( $is_fresh ) {
			$result['label']       = __( 'Your site has been backed up recently', 'wpbp' );
			$result['status']      = 'good';
			$result['description'] = '<p>' . sprintf(
				/* translators: %s: human readable time difference */
				esc_html__( 'The last backup ran %s ago.', 'wpbp' ),
				esc_html( human_time_diff( $timestamp, $now ) )
			) . '</p>';
		} else {
			$result['status']        = 'recommended';
			$result['badge']['color'] = 'orange';
			if ( $has_backup ) {
				$result['label']       = __( 'Your last backup is more than seven days old', 'wpbp' );
				$result['description'] = '<p>' . sprintf(
					/* translators: %s: human readable time difference */
					esc_html__( 'The last backup ran %s ago. Run a new backup to keep your data safe.', 'wpbp' ),
					esc_html( human_time_diff( $timestamp, $now ) )
				) . '</p>';
			} else {
				$result['label']       = __( 'Your site has never been backed up', 'wpbp' );
				$result['description'] = '<p>' . esc_html__( 'No backup has been recorded. Run a backup to keep your data safe.', 'wpbp' ) . '</p>';
			}
		}

		return $result;
	}
}

