<?php
/**
 * Classify a password reset attempt.
 *
 * @param string $user_login Login name of the account.
 * @param string $reset_key  Reset key taken from the reset link.
 * @return string 'valid', 'expired' or 'invalid'.
 */
function wpbp_auth_001( string $user_login, string $reset_key ): string {
	$user_login = trim( $user_login );
	$reset_key  = trim( $reset_key );

	if ( '' === $user_login || '' === $reset_key ) {
		return 'invalid';
	}

	// Unknown login is invalid.
	$user = get_user_by( 'login', $user_login );
	if ( ! $user || ! ( $user instanceof WP_User ) ) {
		return 'invalid';
	}

	// Use WordPress's own reset-key validation.
	$result = check_password_reset_key( $reset_key, $user->user_login );

	if ( $result instanceof WP_User ) {
		return 'valid';
	}

	if ( is_wp_error( $result ) && 'expired_key' === $result->get_error_code() ) {
		return 'expired';
	}

	return 'invalid';
}
