/**
 * Block suspended accounts from signing in.
 */

if ( ! function_exists( 'wpbp_block_suspended_authentication' ) ) {
	/**
	 * Authentication filter callback.
	 *
	 * Runs after WordPress core has verified credentials (priority 20 is after
	 * wp_authenticate_username_password at priority 20 is equal, so we use 30).
	 *
	 * @param WP_User|WP_Error|null $user     User object, error, or null from earlier filters.
	 * @param string                $username Submitted username (unused).
	 * @param string                $password Submitted password (unused).
	 * @return WP_User|WP_Error|null
	 */
	function wpbp_block_suspended_authentication( $user, $username = '', $password = '' ) {
		// Authentication already failed (or nothing authenticated): pass through untouched.
		if ( is_wp_error( $user ) || ! ( $user instanceof WP_User ) ) {
			return $user;
		}

		$suspended = get_user_meta( $user->ID, 'wpbp_suspended', true );

		if ( '1' === (string) $suspended ) {
			return new WP_Error(
				'wpbp_suspended',
				__( '<strong>Error:</strong> This account has been suspended.', 'wpbp' )
			);
		}

		return $user;
	}
}

// Attach directly (boot actions have already fired). Priority 30 runs after
// core's credential checks (wp_authenticate_username_password / email at 20,
// wp_authenticate_cookie at 30 is harmless as it is a separate path).
add_filter( 'authenticate', 'wpbp_block_suspended_authentication', 100, 3 );
