	$name = sanitize_text_field( $application_name );

	$existing = WP_Application_Passwords::get_user_application_passwords( $user_id );
	if ( is_array( $existing ) ) {
		foreach ( $existing as $item ) {
			if ( isset( $item['name'] ) && (string) $item['name'] === $name ) {
				return new WP_Error(
					'wpbp_duplicate_name',
					'An application password with this name already exists for this user.'
				);
			}
		}
	}

	$created = WP_Application_Passwords::create_new_application_password(
		$user_id,
		array( 'name' => $name )
	);

	if ( is_wp_error( $created ) ) {
		return $created;
	}

	$raw_password = $created[0];

	if ( method_exists( 'WP_Application_Passwords', 'chunk_password' ) ) {
		return WP_Application_Passwords::chunk_password( $raw_password );
	}

	return trim( chunk_split( $raw_password, 4, ' ' ) );
}
