function wpbp_auth_004( int $user_id, string $token_to_keep ): int {
    if ( $user_id <= 0 ) {
        return 0;
    }

    $manager = WP_Session_Tokens::get_instance( $user_id );
    if ( ! $manager ) {
        return 0;
    }

    $before = count( (array) $manager->get_all() );
    if ( $before === 0 ) {
        return 0;
    }

    $manager->destroy_others( $token_to_keep );

    $after = count( (array) $manager->get_all() );

    return max( 0, $before - $after );
}
