<?php

if ( ! function_exists( 'wpbp_auth_005' ) ) {
	/**
	 * Verify a password against a user's stored hash and upgrade outdated hashes.
	 *
	 * @param int    $user_id  The user ID.
	 * @param string $password The submitted plaintext password.
	 * @return string 'invalid', 'rehashed' or 'current'.
	 */
	function wpbp_auth_005( int $user_id, string $password ): string {
		$user = get_userdata( $user_id );

		if ( ! $user || empty( $user->user_pass ) ) {
			return 'invalid';
		}

		$hash = $user->user_pass;

		if ( ! wp_check_password( $password, $hash, $user_id ) ) {
			return 'invalid';
		}

		$needs_rehash = function_exists( 'wp_password_needs_rehash' )
			? wp_password_needs_rehash( $hash, $user_id )
			: false;

		if ( $needs_rehash ) {
			wp_set_password( $password, $user_id );
			return 'rehashed';
		}

		return 'current';
	}
}
