<?php
/**
 * Block self-registration from domains listed in the 'wpbp_blocked_domains' option.
 */

function wpbp_check_blocked_registration_domain( $errors, $sanitized_user_login, $user_email ) {
    if ( ! ( $errors instanceof WP_Error ) ) {
        $errors = new WP_Error();
    }

    $user_email = is_string( $user_email ) ? trim( $user_email ) : '';
    if ( '' === $user_email || false === strpos( $user_email, '@' ) ) {
        return $errors;
    }

    $blocked = get_option( 'wpbp_blocked_domains', array() );
    if ( ! is_array( $blocked ) || empty( $blocked ) ) {
        return $errors;
    }

    $blocked = array_filter( array_map( function ( $d ) {
        return is_string( $d ) ? strtolower( trim( $d ) ) : '';
    }, $blocked ) );

    $domain = strtolower( trim( substr( strrchr( $user_email, '@' ), 1 ) ) );
    $domain = rtrim( $domain, '.' );

    if ( '' !== $domain && in_array( $domain, $blocked, true ) ) {
        $errors->add(
            'wpbp_blocked_domain',
            __( '<strong>Error</strong>: Registration from this email domain is not allowed.', 'wpbp' )
        );
    }

    return $errors;
}
add_filter( 'registration_errors', 'wpbp_check_blocked_registration_domain', 10, 3 );
