<?php
/**
 * Route users after login based on their capabilities.
 *
 * @param string           $redirect_to           The redirect destination URL.
 * @param string           $requested_redirect_to The requested redirect destination URL passed as a parameter.
 * @param WP_User|WP_Error $user                  WP_User object if login was successful, WP_Error otherwise.
 * @return string
 */
function my_role_based_login_redirect( $redirect_to, $requested_redirect_to, $user ) {
    // Failed sign-in or anything other than a signed-in user: leave untouched.
    if ( ! ( $user instanceof WP_User ) ) {
        return $redirect_to;
    }

    // Users who can manage options keep the requested destination / WordPress default.
    if ( user_can( $user, 'manage_options' ) ) {
        return $redirect_to;
    }

    // Can edit posts but not manage options: post list screen.
    if ( user_can( $user, 'edit_posts' ) ) {
        return admin_url( 'edit.php' );
    }

    // Cannot edit posts: front page.
    return home_url();
}
add_filter( 'login_redirect', 'my_role_based_login_redirect', 10, 3 );
