function wpbp_caching_002( array $values, array $keys, string $group ): array {
	if ( ! empty( $values ) ) {
		wp_cache_set_multiple( $values, $group );
	}

	if ( empty( $keys ) ) {
		return array();
	}

	$keys    = array_values( $keys );
	$fetched = wp_cache_get_multiple( $keys, $group );
	if ( ! is_array( $fetched ) ) {
		$fetched = array();
	}

	$result = array();
	foreach ( $keys as $key ) {
		if ( ! is_int( $key ) && ! is_string( $key ) ) {
			continue;
		}
		// Preserve falsey values (false, 0, '0', '', etc.) exactly as returned.
		$result[ $key ] = array_key_exists( $key, $fetched ) ? $fetched[ $key ] : false;
	}

	return $result;
}
