function wpbp_caching_003( string $key, string $group, array $salt ): array {
	$value = array(
		'key'   => $key,
		'group' => $group,
		'salt'  => $salt,
	);

	// A salt that deliberately differs from the one used when storing.
	$stale_salt   = $salt;
	$stale_salt[] = 'wpbp_stale_salt';

	if ( function_exists( 'wp_cache_set_salted' ) && function_exists( 'wp_cache_get_salted' ) ) {
		wp_cache_set_salted( $key, $value, $group, $salt, 300 );

		$fresh = wp_cache_get_salted( $key, $group, $salt );
		$stale = wp_cache_get_salted( $key, $group, $stale_salt );

		return array( $fresh, $stale );
	}

	// Fallback for WordPress versions without the salted helpers.
	wp_cache_set(
		$key,
		array(
			'data' => $value,
			'salt' => $salt,
		),
		$group,
		300
	);

	$read = function ( array $use_salt ) use ( $key, $group ) {
		$cached = wp_cache_get( $key, $group );
		if ( is_array( $cached ) && isset( $cached['salt'] ) && $cached['salt'] === $use_salt ) {
			return $cached['data'];
		}
		return false;
	};

	return array( $read( $salt ), $read( $stale_salt ) );
}
