<?php
/**
 * Store a value as a transient and confirm it can be retrieved.
 *
 * @param string $key        Transient name.
 * @param string $value      Value to store.
 * @param int    $expiration Time until expiration in seconds.
 * @return bool True only if the retrieved value matches the stored value.
 */
function wpbp_caching_004( string $key, string $value, int $expiration ): bool {
	$set = set_transient( $key, $value, $expiration );

	if ( ! $set ) {
		return false;
	}

	$retrieved = get_transient( $key );

	if ( false === $retrieved ) {
		return false;
	}

	return $retrieved === $value;
}
