if ( ! function_exists( 'wpbp_caching_009' ) ) {
	/**
	 * Increment and return a hit counter stored in the object cache.
	 *
	 * @param string $counter_key Counter key.
	 * @return int New total.
	 */
	function wpbp_caching_009( string $counter_key ): int {
		$group = 'wpbp_counters';

		// Initialise to 0 only if the key doesn't already exist.
		wp_cache_add( $counter_key, 0, $group );

		$new = wp_cache_incr( $counter_key, 1, $group );

		if ( false === $new ) {
			// Fallback if the cache backend couldn't increment.
			$current = wp_cache_get( $counter_key, $group );
			$new     = ( is_numeric( $current ) ? (int) $current : 0 ) + 1;
			wp_cache_set( $counter_key, $new, $group );
		}

		return (int) $new;
	}
}
