/**
 * Create a Subscriber user with the supplied login and return the WP_User object.
 *
 * @param string $login Desired user login.
 * @return WP_User|WP_Error
 */
function wpbp_comments_users_001( string $login ): WP_User|WP_Error {
	$login = sanitize_user( $login, true );

	if ( '' === $login ) {
		return new WP_Error( 'wpbp_invalid_login', __( 'Invalid user login supplied.', 'default' ) );
	}

	if ( username_exists( $login ) ) {
		return new WP_Error( 'wpbp_login_exists', __( 'That user login already exists.', 'default' ) );
	}

	$user_id = wp_insert_user(
		array(
			'user_login' => $login,
			'user_pass'  => wp_generate_password( 24, true, true ),
			'role'       => 'subscriber',
		)
	);

	if ( is_wp_error( $user_id ) ) {
		return $user_id;
	}

	$user = get_userdata( $user_id );

	if ( ! ( $user instanceof WP_User ) ) {
		return new WP_Error( 'wpbp_user_retrieval_failed', __( 'Unable to retrieve the newly created user.', 'default' ) );
	}

	return $user;
}
