function wpbp_comments_users_006( int $user_id, string $new_password, string $session_token ): bool {
    if ( $user_id <= 0 || '' === $new_password ) {
        return false;
    }

    $user = get_userdata( $user_id );
    if ( ! $user ) {
        return false;
    }

    $manager = WP_Session_Tokens::get_instance( $user_id );

    // Remember the session being kept, in case the update clears sessions.
    $kept_session = ( '' !== $session_token ) ? $manager->get( $session_token ) : null;

    // wp_update_user() hashes the password before storing it.
    $result = wp_update_user(
        array(
            'ID'        => $user_id,
            'user_pass' => $new_password,
        )
    );

    if ( is_wp_error( $result ) ) {
        return false;
    }

    // Re-fetch the manager and restore the kept session if it was wiped during the update.
    $manager = WP_Session_Tokens::get_instance( $user_id );
    if ( '' !== $session_token && $kept_session && ! $manager->verify( $session_token ) ) {
        $manager->update( $session_token, $kept_session );
    }

    // Revoke all of this user's other sessions, keeping the supplied one.
    if ( '' !== $session_token ) {
        $manager->destroy_others( $session_token );
    } else {
        $manager->destroy_all();
    }

    return true;
}
