function wpbp_dates_time_001( int $post_id, string $format ): string {
	$post = get_post( $post_id );
	if ( ! $post ) {
		return '';
	}

	$tz = wp_timezone();

	// Prefer the absolute (GMT) moment of publication.
	$dt = get_post_datetime( $post, 'date', 'gmt' );

	// Fallback for posts without a GMT date (e.g. drafts): use local date in site timezone.
	if ( ! $dt ) {
		$dt = get_post_datetime( $post, 'date', 'local' );
	}

	if ( ! $dt ) {
		return '';
	}

	// Convert to the site's timezone; the offset is resolved for that specific moment (DST-aware).
	$local = $dt->setTimezone( $tz );

	return $local->format( $format );
}
