function wpbp_dates_time_002( string $local_datetime ): array {
	$tz  = wp_timezone();
	$utc = new DateTimeZone( 'UTC' );

	$dt     = DateTimeImmutable::createFromFormat( 'Y-m-d H:i:s', trim( $local_datetime ), $tz );
	$errors = DateTimeImmutable::getLastErrors();

	if ( false === $dt || ( is_array( $errors ) && ( $errors['warning_count'] > 0 || $errors['error_count'] > 0 ) ) ) {
		return array(
			'gmt'   => '',
			'local' => '',
		);
	}

