function wpbp_dates_time_004( int $post_id ): string {
	$post = get_post( $post_id );
	if ( ! $post ) {
		return '';
	}

	// Publication moment as a UTC Unix timestamp.
	$timestamp = get_post_time( 'U', true, $post );
	if ( false === $timestamp || '' === $timestamp || null === $timestamp ) {
		return '';
	}
	$timestamp = (int) $timestamp;

	$now  = time();
	$diff = $now - $timestamp;

	if ( $diff >= 0 && $diff < WEEK_IN_SECONDS ) {
		return human_time_diff( $timestamp, $now ) . ' ago';
	}

	// wp_date() uses the site's timezone by default.
	$format = get_option( 'date_format' );
	if ( empty( $format ) ) {
		$format = 'F j, Y';
	}

	return (string) wp_date( $format, $timestamp );
}
