if ( ! function_exists( 'wpbp_dates_time_005' ) ) {
	/**
	 * Convert a UTC 'Y-m-d H:i:s' string to an ISO 8601 string in the site's timezone.
	 *
	 * Works with a named timezone (timezone_string) or a manual UTC offset (gmt_offset),
	 * including fractional offsets such as +5.5 or -3.75.
	 *
	 * @param string $utc_datetime Datetime in UTC, formatted 'Y-m-d H:i:s'.
	 * @return string ISO 8601 (PHP 'c') formatted datetime in the site's timezone, or empty string on failure.
	 */
	function wpbp_dates_time_005( string $utc_datetime ): string {
		$utc = new DateTimeZone( 'UTC' );
		$dt  = DateTimeImmutable::createFromFormat( '!Y-m-d H:i:s', trim( $utc_datetime ), $utc );

		if ( false === $dt ) {
			return '';
		}

		if ( function_exists( 'wp_timezone' ) ) {
			$tz = wp_timezone();
		} else {
			$tz_string = get_option( 'timezone_string' );
			if ( is_string( $tz_string ) && '' !== $tz_string ) {
				try {
					$tz = new DateTimeZone( $tz_string );
				} catch ( Exception $e ) {
					$tz = $utc;
				}
			} else {
				$offset        = (float) get_option( 'gmt_offset', 0 );
				$sign          = ( $offset < 0 ) ? '-' : '+';
				$total_minutes = (int) round( abs( $offset ) * 60 );
				$hours         = intdiv( $total_minutes, 60 );
				$minutes       = $total_minutes % 60;
				try {
					$tz = new DateTimeZone( sprintf( '%s%02d:%02d', $sign, $hours, $minutes ) );
				} catch ( Exception $e ) {
					$tz = $utc;
				}
			}
		}

		return $dt->setTimezone( $tz )->format( 'c' );
	}
}
