function wpbp_gb_block_api_003( string $content ): array {
	$counts = array();

	if ( '' === $content || ! class_exists( 'WP_Block_Processor' ) ) {
		return $counts;
	}

	$processor = new WP_Block_Processor( $content );

	// next_block() visits every explicit block opener (including nested and void blocks).
	while ( $processor->next_block() ) {
		$type = $processor->get_block_type();

		if ( null === $type || '' === $type ) {
			continue;
		}

		if ( ! isset( $counts[ $type ] ) ) {
			$counts[ $type ] = 0;
		}

		$counts[ $type ]++;
	}

	return $counts;
}
