/**
 * Render callback for wpbp/roster.
 *
 * @param array    $attributes Block attributes.
 * @param string   $content    Rendered inner blocks.
 * @param WP_Block $block      Block instance.
 * @return string
 */
function wpbp_roster_render_roster( $attributes, $content, $block = null ) {
	return '<div class="wpbp-roster">' . $content . '</div>';
}

/**
 * Render callback for wpbp/roster-member.
 *
 * @param array    $attributes Block attributes.
 * @param string   $content    Block content.
 * @param WP_Block $block      Block instance.
 * @return string
 */
function wpbp_roster_render_member( $attributes, $content, $block = null ) {
	$team = '';

	if ( $block instanceof WP_Block && isset( $block->context['wpbp/team'] ) && is_string( $block->context['wpbp/team'] ) ) {
		$team = trim( $block->context['wpbp/team'] );
	}

	if ( '' === $team ) {
		$team = 'unassigned';
	}

	return '<span class="wpbp-roster-member">' . esc_html( 'Team: ' . $team ) . '</span>';
}

