	register_block_type_from_metadata(
		__DIR__ . '/blocks/roster',

array(
			'render_callback' => 'wpbp_roster_render_roster',
		)
	);

	register_block_type_from_metadata(
		__DIR__ . '/blocks/roster-member',
		array(
			'render_callback' => 'wpbp_roster_render_member',
		)
	);
}
