    // Panel is a container: only its children contribute.
    add_filter(
        'excerpt_allowed_wrapper_blocks',
        static function ( $wrappers ) {
            $wrappers = is_array( $wrappers ) ? $wrappers : array();
            if ( ! in_array( 'wpbp/panel', $wrappers, true ) ) {
                $wrappers[] = 'wpbp/panel';
            }
            return $wrappers;
        }
    );

    // Note blocks contribute their text; the aside block stays excluded.
    add_filter(
        'excerpt_allowed_blocks',
        static function ( $allowed ) {
            $allowed = is_array( $allowed ) ? $allowed : array();
            foreach ( array( 'wpbp/note', 'wpbp/panel' ) as $name ) {
                if ( ! in_array( $name, $allowed, true ) ) {
                    $allowed[] = $name;
                }
            }
            return array_values(
                array_filter(
                    $allowed,
                    static function ( $name ) {
                        return 'wpbp/aside' !== $name;
                    }
                )
            );
        },
        20
    );
}
