	$post = get_post( $pattern_id );
	if ( ! $post || 'wp_block' !== $post->post_type ) {
		return '';
	}

	// Collect overridable blocks (name => bound attributes) from the pattern.
	$overridable = array();
	$walk        = function ( array $blocks ) use ( &$walk, &$overridable ) {
		foreach ( $blocks as $block ) {
			$meta = $block['attrs']['metadata'] ?? null;
			if ( is_array( $meta ) && ! empty( $meta['name'] ) && ! empty( $meta['bindings'] ) && is_array( $meta['bindings'] ) ) {
				foreach ( $meta['bindings'] as $attr => $binding ) {
					if ( is_array( $binding ) && isset( $binding['source'] ) && 'core/pattern-overrides' === $binding['source'] ) {
						$overridable[ $meta['name'] ][] = $attr;
					}
				}
			}
			if ( ! empty( $block['innerBlocks'] ) ) {
				$walk( $block['innerBlocks'] );
			}
		}
	};
	$walk( parse_blocks( $post->post_content ) );

	// Build the content attribute of the core/block instance.
	$content = array();
	foreach ( $overrides as $name => $text ) {
		$name = (string) $name;
		if ( ! isset( $overridable[ $name ] ) || ! is_scalar( $text ) ) {
			continue;
		}
		foreach ( array_unique( $overridable[ $name ] ) as $attr ) {
			$content[ $name ][ $attr ] = wp_kses_post( (string) $text );
		}
	}

	$attrs = array( 'ref' => $pattern_id );
	if ( ! empty( $content ) ) {
		$attrs['content'] = $content;
	}

	return render_block(
		array(
			'blockName'    => 'core/block',
			'attrs'        => $attrs,
			'innerBlocks'  => array(),
			'innerHTML'    => '',
			'innerContent' => array(),
		)
	);
}
