	$attributes = array();
	$existing   = get_post_meta( $post->ID, '_wp_ignored_hooked_blocks', true );
	if ( ! empty( $existing ) ) {
		$decoded = is_string( $existing ) ? json_decode( $existing, true ) : $existing;
		if ( is_array( $decoded ) && ! empty( $decoded ) ) {
			$attributes['metadata'] = array( 'ignoredHookedBlocks' => $decoded );
		}
	}

	$markup = get_comment_delimited_block_content( 'core/post-content', $attributes, (string) $post->post_content );

	$processed = apply_block_hooks_to_content_from_post_object( $markup, $post, $callback );

