function wpbp_gb_font_library_002(): bool {
    if ( ! function_exists( 'wp_register_font_collection' ) ) {
        return false;
    }

    // Avoid duplicate registration.
    if ( class_exists( 'WP_Font_Library' ) ) {
        $existing = WP_Font_Library::get_instance()->get_font_collection( 'wpbp-fonts' );
        if ( $existing && ! is_wp_error( $existing ) ) {
            return true;
        }
    }

    $result = wp_register_font_collection(
        'wpbp-fonts',
        array(
            'name'          => 'WPBP Fonts',
            'description'   => 'Font collection for WPBP.',
            'font_families' => array(
                array(
                    'font_family_settings' => array(
                        'name'       => 'Bench Sans',
                        'slug'       => 'bench-sans',
                        'fontFamily' => '"Bench Sans", sans-serif',
                    ),
                    'categories'           => array(),
                ),
            ),
            'categories'    => array(),
        )
    );

    return ! is_wp_error( $result ) && false !== $result && null !== $result;
}

