function wpbp_gb_interactivity_api_009( array $settings ): array {
	$namespace = 'wpbp/merge';

	if ( function_exists( 'wp_interactivity_state' ) ) {
		// wp_interactivity_state() recursively merges the supplied data into
		// any state already registered for this namespace, and returns the result.
		return wp_interactivity_state(
			$namespace,
			array(
				'settings' => $settings,
			)
		);
	}

	// Fallback for environments without the Interactivity API (WP < 6.5).
	static $fallback_state = array();

	if ( ! isset( $fallback_state[ $namespace ] ) ) {
		$fallback_state[ $namespace ] = array();
	}

	$fallback_state[ $namespace ] = array_replace_recursive(
		$fallback_state[ $namespace ],
		array( 'settings' => $settings )
	);

	return $fallback_state[ $namespace ];
}
