function wpbp_hooks_003( callable $callback ): bool {
	$hook     = 'wpbp_remove_filter';
	$priority = 0;

	// has_filter() returns the priority (int, possibly 0) or false; compare strictly.
	$before = has_filter( $hook, $callback );
	if ( false === $before || $priority !== (int) $before ) {
		return false;
	}

	$removed = remove_filter( $hook, $callback, $priority );

	$after = has_filter( $hook, $callback );

	return ( true === $removed && false === $after );
}
