	global $wp_filter;

	$new_priority = (int) $new_priority;

	if ( ! isset( $wp_filter[ $hook ] ) || ! is_object( $wp_filter[ $hook ] ) || empty( $wp_filter[ $hook ]->callbacks ) ) {
		return false;
	}

	if ( false === has_filter( $hook, $callback ) ) {
		return false;
	}

