	$accepted_args = 1;
	$first         = true;

	foreach ( $wp_filter[ $hook ]->callbacks as $priority => $callbacks ) {
		if ( isset( $callbacks[ $id ] ) ) {
			$found[] = (int) $priority;
			if ( $first ) {
				$accepted_args = isset( $callbacks[ $id ]['accepted_args'] ) ? (int) $callbacks[ $id ]['accepted_args'] : 1;
				$first         = false;
