function wpbp_html_api_010( string $raw_href ): bool {
	// The HTML tokenizer turns raw NUL bytes in attribute values into U+FFFD.
	$raw_href = str_replace( "\0", "\xEF\xBF\xBD", $raw_href );

	// Apply attribute-context character reference decoding (handles missing semicolons rules).
	$decoded = WP_HTML_Decoder::decode_attribute( $raw_href );

	// URL parser: strip leading/trailing C0 control or space characters.
	$decoded = trim( $decoded, "\x00..\x20" );

	// URL parser: remove all ASCII tab and newline characters anywhere in the input.
	$decoded = str_replace( array( "\t", "\n", "\r" ), '', $decoded );

	return 1 === preg_match( '/^javascript:/i', $decoded );
}
