function wpbp_http_api_002( string $url ): array {
    $result = array(
        'safe' => false,
        'body' => '',
    );

    if ( '' === trim( $url ) ) {
        return $result;
    }

    // Ask WordPress whether the URL is safe to request.
    if ( ! function_exists( 'wp_http_validate_url' ) ) {
        return $result;
    }

    $validated = wp_http_validate_url( $url );
    if ( false === $validated ) {
        return $result;
    }

    $result['safe'] = true;

    // Fetch with the validating GET helper (applies reject_unsafe_urls).
    $response = wp_safe_remote_get( $url );

    if ( is_wp_error( $response ) ) {
        return $result;
    }

    if ( 200 === (int) wp_remote_retrieve_response_code( $response ) ) {
        $result['body'] = (string) wp_remote_retrieve_body( $response );
    }

    return $result;
}
