	$links   = array();
	$headers = wp_remote_retrieve_headers( $response );
	if ( is_object( $headers ) && method_exists( $headers, 'getValues' ) ) {
		$values = $headers->getValues( 'link' );
		if ( is_array( $values ) ) {
			$links = $values;
		}
	}
	if ( empty( $links ) ) {
		$link = wp_remote_retrieve_header( $response, 'link' );
		if ( is_array( $link ) ) {
