<?php

if ( ! function_exists( 'wpbp_http_api_007' ) ) {
	/**
	 * Fetch a URL and report the status message, wpbp_session cookie value,
	 * and a sorted list of all cookie names set by the response.
	 *
	 * @param string $url The URL to fetch.
	 * @return array{message:string,session:string,cookies:array<int,string>}
	 */
	function wpbp_http_api_007( string $url ): array {
		$result = array(
			'message' => '',
			'session' => '',
			'cookies' => array(),
		);

		$response = wp_remote_get( $url );

		if ( is_wp_error( $response ) ) {
			return $result;
		}

		$result['message'] = (string) wp_remote_retrieve_response_message( $response );

		$cookies = wp_remote_retrieve_cookies( $response );
		$names   = array();

		if ( is_array( $cookies ) ) {
			foreach ( $cookies as $cookie ) {
				if ( is_object( $cookie ) && isset( $cookie->name ) ) {
					$name    = (string) $cookie->name;
					$names[] = $name;

					if ( 'wpbp_session' === $name && '' === $result['session'] ) {
						$result['session'] = isset( $cookie->value ) ? (string) $cookie->value : '';
					}
				}
			}
		}

		$names = array_values( array_unique( $names ) );
		sort( $names, SORT_STRING );

		$result['cookies'] = $names;

		return $result;
	}
}
