	 * Fetch a URL over HTTP, caching successful (200) response bodies for five minutes.
	 *
	 * @param string $url The URL to fetch.
	 * @return string Response body, or an empty string on failure.
	 */
	function wpbp_http_api_008( string $url ): string {
		$transient_key = 'wpbp_http_' . md5( $url );

		$cached = get_transient( $transient_key );
		if ( false !== $cached && is_string( $cached ) ) {
			return $cached;
		}

		$response = wp_remote_get( $url );

		if ( is_wp_error( $response ) ) {
			return '';
		}

		if ( 200 !== (int) wp_remote_retrieve_response_code( $response ) ) {
			return '';
		}

		$body = wp_remote_retrieve_body( $response );
		if ( ! is_string( $body ) ) {
			return '';
		}

		set_transient( $transient_key, $body, 5 * MINUTE_IN_SECONDS );

		return $body;
	}
}
