function wpbp_mail_url_001( string $url ): string {
	$url = trim( $url );

	if ( '' === $url ) {
		return '';
	}

	$protocols = array( 'https', 'http' );

	$first_char = $url[0];

	// Relative URLs, fragments, queries and protocol-relative URLs are left to WordPress.
	$is_relative = in_array( $first_char, array( '/', '#', '?' ), true );

	// Detect an existing scheme (e.g. "http:", "mailto:"), but treat "host:port" as scheme-less.
	$has_scheme = (bool) preg_match( '#^[a-z][a-z0-9+.\-]*:#i', $url )
		&& ! preg_match( '#^[^/?\#:]+:\d+(?:[/?\#]|$)#', $url );

	// Mirror WordPress' own behavior for bare "file.php" style relative paths.
	$is_php_file = (bool) preg_match( '/^[a-z0-9-]+?\.php/i', $url );

	if ( ! $is_relative && ! $has_scheme && ! $is_php_file ) {
		// WordPress would add http://; prefer https:// instead.
		$url = 'https://' . $url;
	}

	return esc_url_raw( $url, $protocols );
}
