if ( ! function_exists( 'wpbp_media_002' ) ) {
	/**
	 * Returns the given HTML after WordPress applies its media tag optimizations
	 * (responsive srcset/sizes, lazy loading, decoding, fetchpriority, iframe lazy loading, etc.).
	 *
	 * @param string      $html    The HTML content to filter.
	 * @param string|null $context Optional context (e.g. 'the_content'). Defaults to 'the_content'.
	 * @return string The filtered HTML.
	 */
	function wpbp_media_002( string $html, ?string $context = null ): string {
		if ( '' === $html ) {
			return $html;
		}

		if ( null === $context || '' === $context ) {
			$context = 'the_content';
		}

		if ( function_exists( 'wp_filter_content_tags' ) ) {
			$result = wp_filter_content_tags( $html, $context );
		} elseif ( function_exists( 'wp_make_content_images_responsive' ) ) {
			// Fallback for very old WordPress versions.
			$result = wp_make_content_images_responsive( $html );
		} else {
			$result = $html;
		}

		return is_string( $result ) ? $result : $html;
	}
}
