function wpbp_media_009( array $files, int $post_id ): array {
	if ( ! function_exists( 'media_handle_sideload' ) ) {
		require_once ABSPATH . 'wp-admin/includes/file.php';
		require_once ABSPATH . 'wp-admin/includes/media.php';
		require_once ABSPATH . 'wp-admin/includes/image.php';
	}

	$ids = array();

	foreach ( $files as $file ) {
		if ( ! is_array( $file ) || empty( $file['name'] ) || empty( $file['tmp_name'] ) ) {
			continue;
		}

		$tmp_name = (string) $file['tmp_name'];
		if ( ! is_file( $tmp_name ) || ! is_readable( $tmp_name ) ) {
			continue;
		}

		$file_array = array(
			'name'     => (string) $file['name'],
			'tmp_name' => $tmp_name,
		);

		// media_handle_sideload() uses wp_handle_sideload() with test_form disabled,
		// so form validation is skipped and the file is moved into the uploads directory.
		$attachment_id = media_handle_sideload( $file_array, $post_id );

		if ( is_wp_error( $attachment_id ) ) {
			continue;
		}

		$ids[] = (int) $attachment_id;
	}

	return $ids;
}
