/**
 * Plugin Name: WPBP Reader
 * Description: Reader plugin that maintains its own stored settings across activation, upgrades and uninstall.
 * Version: 2.0.0
 * Requires at least: 5.0
 * License: GPL-2.0-or-later
 * Text Domain: wpbp-reader
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

define( 'WPBP_READER_SETTINGS_VERSION', 2 );

/**
 * Default settings for the current version.
 *
 * @return array
 */
function wpbp_reader_default_settings() {
	return array(
		'version'     => WPBP_READER_SETTINGS_VERSION,
		'per_page'    => 10,
		'show_covers' => true,
	);
}

/**
 * Activation: seed defaults only when nothing is stored yet.
 */
function wpbp_reader_activate() {
	if ( false === get_option( 'wpbp_reader_settings', false ) ) {
		add_option( 'wpbp_reader_settings', wpbp_reader_default_settings() );
	}
}
register_activation_hook( __FILE__, 'wpbp_reader_activate' );

/**
 * Upgrade settings left behind by older versions (version 1 stored only perPage).
 */
function wpbp_reader_maybe_upgrade() {
	$settings = get_option( 'wpbp_reader_settings', false );

	if ( ! is_array( $settings ) ) {
		return;
	}

	$stored_version = isset( $settings['version'] ) ? (int) $settings['version'] : 1;

	if ( $stored_version >= WPBP_READER_SETTINGS_VERSION ) {
		return;
	}

	$defaults = wpbp_reader_default_settings();
	$upgraded = $settings;

	// Carry over the reader's page size from version 1.
	$per_page = 0;
	if ( isset( $settings['perPage'] ) ) {
		$per_page = absint( $settings['perPage'] );
	} elseif ( isset( $settings['per_page'] ) ) {
		$per_page = absint( $settings['per_page'] );
	}
	if ( $per_page < 1 ) {
		$per_page = $defaults['per_page'];
	}

	unset( $upgraded['perPage'] );
	$upgraded['per_page'] = $per_page;

	// Fill in defaults that did not exist in version 1.
	if ( ! array_key_exists( 'show_covers', $upgraded ) ) {
		$upgraded['show_covers'] = $defaults['show_covers'];
	}

	// Stamp current version.
	$upgraded['version'] = WPBP_READER_SETTINGS_VERSION;

	update_option( 'wpbp_reader_settings', $upgraded );

	$count = (int) get_option( 'wpbp_reader_upgrades', 0 );
	update_option( 'wpbp_reader_upgrades', $count + 1 );
}
add_action( 'plugins_loaded', 'wpbp_reader_maybe_upgrade' );

/**
 * Uninstall callback: remove the plugin's options.
 */
function wpbp_reader_uninstall() {
	delete_option( 'wpbp_reader_settings' );
	delete_option( 'wpbp_reader_upgrades' );
}
register_uninstall_hook( __FILE__, 'wpbp_reader_uninstall' );
"}}

