/**
 * Plugin Name: WPBP Reader
 * Description: Adds a Settings link and a Docs link to its own row on the Plugins screen.
 * Version: 1.0.0
 * License: GPL-2.0-or-later
 * Text Domain: wpbp-reader
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Return this plugin's basename (e.g. "some-dir/wpbp-reader.php"), derived at runtime.
 *
 * @return string
 */
function wpbp_reader_basename() {
	return plugin_basename( __FILE__ );
}

/**
 * Prepend a Settings link to this plugin's action links, keeping existing ones.
 *
 * @param array $links Existing action links.
 * @return array
 */
function wpbp_reader_action_links( $links ) {
	$links = is_array( $links ) ? $links : array();

	$settings = '<a href="' . esc_url( admin_url( 'options-general.php?page=wpbp-reader' ) ) . '">'
		. esc_html__( 'Settings', 'wpbp-reader' ) . '</a>';

	array_unshift( $links, $settings );

	return $links;
}
add_filter( 'plugin_action_links_' . plugin_basename( __FILE__ ), 'wpbp_reader_action_links' );

/**
 * Append a Docs link to this plugin's row meta only, keeping existing entries.
 *
 * @param array  $plugin_meta Existing meta entries.
 * @param string $plugin_file Plugin file being rendered, relative to the plugins directory.
 * @return array
 */
function wpbp_reader_row_meta( $plugin_meta, $plugin_file ) {
	if ( wpbp_reader_basename() !== $plugin_file ) {
		return $plugin_meta;
	}

	$plugin_meta   = is_array( $plugin_meta ) ? $plugin_meta : array();
	$plugin_meta[] = '<a href="' . esc_url( 'https://example.org/wpbp-reader-docs' ) . '">'
		. esc_html__( 'Docs', 'wpbp-reader' ) . '</a>';

	return $plugin_meta;
}
add_filter( 'plugin_row_meta', 'wpbp_reader_row_meta', 10, 2 );

/**
 * Register a minimal settings page so the Settings link has a destination.
 */
function wpbp_reader_admin_menu() {
	add_options_page(
		__( 'WPBP Reader', 'wpbp-reader' ),
		__( 'WPBP Reader', 'wpbp-reader' ),
		'manage_options',
		'wpbp-reader',
		'wpbp_reader_render_page'
	);
}
add_action( 'admin_menu', 'wpbp_reader_admin_menu' );

/**
 * Render the settings page.
 */
function wpbp_reader_render_page() {
	if ( ! current_user_can( 'manage_options' ) ) {
		return;
	}
	?>
	<div class="wrap">
		<h1><?php echo esc_html__( 'WPBP Reader', 'wpbp-reader' ); ?></h1>
		<p><?php echo esc_html__( 'There are no settings yet.', 'wpbp-reader' ); ?></p>
	</div>
	<?php
}
