function wpbp_post_meta_003( int $post_id, string $meta_key, string $value ): bool {
	global $wpdb;

	if ( $post_id <= 0 || '' === $meta_key ) {
		return false;
	}

	// For non-empty values, delete_post_meta() only removes rows whose value matches.
	// wp_slash() is needed because the metadata API unslashes the value.
	if ( '' !== $value ) {
		return (bool) delete_post_meta( $post_id, $meta_key, wp_slash( $value ) );
	}

	// An empty value passed to delete_post_meta() would delete ALL values for the key,
	// so handle exact empty-string matches manually by meta ID.
	$meta_ids = $wpdb->get_col(
		$wpdb->prepare(
			"SELECT meta_id FROM {$wpdb->postmeta} WHERE post_id = %d AND meta_key = %s AND meta_value = ''",
			$post_id,
			$meta_key
		)
	);

	if ( empty( $meta_ids ) ) {
		return false;
	}

	$deleted = false;
	foreach ( $meta_ids as $meta_id ) {
		if ( delete_metadata_by_mid( 'post', (int) $meta_id ) ) {
			$deleted = true;
		}
	}

	return $deleted;
}
