function wpbp_post_meta_005( int $post_id, string $meta_key, string $json ): string {
	if ( $post_id <= 0 || '' === $meta_key ) {
		return '';
	}

	// update_post_meta() runs wp_unslash() on the value internally,
	// which would strip the backslashes from escaped quotes (\").
	// Slashing first makes the stored value match the original input.
	update_post_meta( $post_id, $meta_key, wp_slash( $json ) );

	// update_post_meta() returns false when the value is unchanged,
	// so verify by reading back the stored value.
	$stored = get_post_meta( $post_id, $meta_key, true );

	return is_string( $stored ) ? $stored : '';
}
