	if ( ! taxonomy_exists( $taxonomy ) || ! get_post( $post_id ) ) {
		return array();
	}

	$term_ids = array();
	foreach ( $submitted_term_ids as $raw_id ) {
		if ( is_int( $raw_id ) ) {
			$id = $raw_id;
		} elseif ( is_string( $raw_id ) && ctype_digit( trim( $raw_id ) ) ) {
			$id = (int) trim( $raw_id );
		} else {
			continue;
		}
		if ( $id <= 0 ) {
			continue;
		}
		// Only accept terms that already exist in this taxonomy.
		$term = get_term( $id, $taxonomy );
		if ( $term instanceof WP_Term ) {
			$term_ids[] = (int) $term->term_id;
		}
	}

	$term_ids = array_values( array_unique( $term_ids ) );

	// Integers guarantee IDs are used (strings would be treated as names and create new terms).
	wp_set_object_terms( $post_id, $term_ids, $taxonomy, false );

	$current = wp_get_object_terms( $post_id, $taxonomy, array( 'fields' => 'ids' ) );
	if ( is_wp_error( $current ) || ! is_array( $current ) ) {
		return array();
	}

	return array_map( 'intval', $current );
}

