function wpbp_post_types_taxonomy_012( int $term_id, int $fallback_term_id ): bool {
	if ( $term_id === $fallback_term_id ) {
		return false;
	}

	$term     = get_term( $term_id, 'category' );
	$fallback = get_term( $fallback_term_id, 'category' );

	if ( ! $term || is_wp_error( $term ) || ! $fallback || is_wp_error( $fallback ) ) {
		return false;
	}

	// Default category cannot be deleted.
	if ( (int) get_option( 'default_category' ) === $term_id ) {
		return false;
	}

	$object_ids = get_objects_in_term( $term_id, 'category' );
	if ( is_wp_error( $object_ids ) ) {
		$object_ids = array();
	}

	$result = wp_delete_term(
		$term_id,
		'category',
		array(
			'default'       => $fallback_term_id,
			'force_default' => true,
		)
	);

	if ( true !== $result ) {
		return false;
	}

	// Safety net: make sure every formerly-assigned post has the fallback, keeping other categories.
	foreach ( $object_ids as $object_id ) {
		$object_id = (int) $object_id;
		if ( ! has_term( $fallback_term_id, 'category', $object_id ) ) {
			wp_set_object_terms( $object_id, array( $fallback_term_id ), 'category', true );
		}
	}

	return true;
}
