function wpbp_post_types_taxonomy_013( int $term_id ): array {
	$term_id = absint( $term_id );

	if ( ! $term_id ) {
		return array();
	}

	// get_ancestors() returns ancestors ordered from immediate parent up to the top-level ancestor.
	$ancestors = get_ancestors( $term_id, 'category', 'taxonomy' );

	if ( empty( $ancestors ) || ! is_array( $ancestors ) ) {
		return array();
	}

	// Reverse so the order runs from top-level ancestor down to immediate parent.
	$ancestors = array_reverse( $ancestors );

	return array_values( array_map( 'intval', $ancestors ) );
}
