function wpbp_posts_lifecycle_003( int $acting_user_id, string $html ): int {
	global $wp_filter, $wpdb;

	wp_set_current_user( $acting_user_id );

	$tags  = array( 'content_save_pre', 'pre_post_content', 'content_filtered_save_pre' );
	$saved = array();

	foreach ( $tags as $tag ) {
		$saved[ $tag ] = array_key_exists( $tag, $wp_filter ) ? $wp_filter[ $tag ] : null;
		unset( $wp_filter[ $tag ] );
	}

	$post_id = 0;

	try {
		$post_id = wp_insert_post(
			array(
				'post_type'    => 'post',
				'post_status'  => 'publish',
				'post_author'  => $acting_user_id,
				'post_title'   => wp_slash( wp_trim_words( wp_strip_all_tags( $html ), 8, '' ) ),
				'post_content' => wp_slash( $html ),
			),
			false
		);
	} finally {
		foreach ( $tags as $tag ) {
			if ( null === $saved[ $tag ] ) {
				unset( $wp_filter[ $tag ] );
			} else {
				$wp_filter[ $tag ] = $saved[ $tag ];
			}
		}
		// Re-establish normal kses filtering for the current (acting) user.
		wp_set_current_user( $acting_user_id );
		kses_init();
	}

	$post_id = (int) $post_id;

	if ( $post_id > 0 ) {
		$stored = $wpdb->get_var( $wpdb->prepare( "SELECT post_content FROM {$wpdb->posts} WHERE ID = %d", $post_id ) );
		if ( $stored !== $html ) {
			$wpdb->update( $wpdb->posts, array( 'post_content' => $html ), array( 'ID' => $post_id ) );
			clean_post_cache( $post_id );
		}
	}

	return $post_id;
}
