function wpbp_posts_lifecycle_005( string $title, string $utc_datetime ): int {
	$utc_tz = new DateTimeZone( 'UTC' );
	$dt     = DateTime::createFromFormat( 'Y-m-d H:i:s', $utc_datetime, $utc_tz );

	if ( ! $dt ) {
		return 0;
	}

	$timestamp = $dt->getTimestamp();
	$gmt_date  = $dt->format( 'Y-m-d H:i:s' );

	// Convert to site's timezone.
	$local_date = get_date_from_gmt( $gmt_date, 'Y-m-d H:i:s' );

	$post_id = wp_insert_post(
		array(
			'post_title'    => $title,
			'post_content'  => '',
			'post_status'   => 'future',
			'post_type'     => 'post',
			'post_date'     => $local_date,
			'post_date_gmt' => $gmt_date,
			'edit_date'     => true,
		),
		true
	);

	if ( is_wp_error( $post_id ) || ! $post_id ) {
		return 0;
	}

	$post_id = (int) $post_id;

	// Ensure the status is 'future' and dates are correct.
	global $wpdb;
	$wpdb->update(
		$wpdb->posts,
		array(
			'post_status'   => 'future',
			'post_date'     => $local_date,
			'post_date_gmt' => $gmt_date,
		),
		array( 'ID' => $post_id )
	);
	clean_post_cache( $post_id );

	// Make sure the scheduled publish event is queued at exactly that moment.
	wp_clear_scheduled_hook( 'publish_future_post', array( $post_id ) );
	wp_schedule_single_event( $timestamp, 'publish_future_post', array( $post_id ) );

	return $post_id;
}
