function wpbp_posts_lifecycle_009( int $post_id, bool $permanently ): bool {
	$post = get_post( $post_id );
	if ( ! $post ) {
		return false;
	}

	if ( $permanently ) {
		// Force delete removes the post row and all of its metadata.
		$result = wp_delete_post( $post_id, true );
		return ( $result instanceof WP_Post );
	}

	// If trash is disabled, wp_trash_post() would permanently delete the post.
	// Refuse to do that, since the caller asked only for a Trash move.
	if ( ! defined( 'EMPTY_TRASH_DAYS' ) || ! EMPTY_TRASH_DAYS ) {
		return false;
	}

	// Moves the post to the Trash, keeping its metadata so it can be restored.
	$result = wp_trash_post( $post_id );
	return ( $result instanceof WP_Post );
}
