function wpbp_posts_lifecycle_010( string $path, string $post_type ): int {
	global $wpdb;

	$path = trim( $path, '/' );
	if ( $path === '' || $post_type === '' ) {
		return 0;
	}

	$segments = array();
	foreach ( explode( '/', $path ) as $part ) {
		$part = sanitize_title( rawurldecode( $part ) );
		if ( $part !== '' ) {
			$segments[] = $part;
		}
	}

	if ( empty( $segments ) ) {
		return 0;
	}

	$count = count( $segments );
	$last  = $segments[ $count - 1 ];

	$candidates = $wpdb->get_results(
		$wpdb->prepare(
			"SELECT ID, post_parent FROM {$wpdb->posts}
			 WHERE post_name = %s AND post_type = %s
			 AND post_status NOT IN ('trash', 'auto-draft')
			 ORDER BY (post_status = 'publish') DESC, ID ASC",
			$last,
			$post_type
		)
	);

	if ( empty( $candidates ) ) {
		return 0;
	}

	foreach ( $candidates as $candidate ) {
		$parent_id = (int) $candidate->post_parent;
		$matched   = true;

		for ( $i = $count - 2; $i >= 0; $i-- ) {
			if ( $parent_id <= 0 ) {
				$matched = false;
				break;
			}
			$parent = $wpdb->get_row(
				$wpdb->prepare(
					"SELECT ID, post_name, post_parent FROM {$wpdb->posts} WHERE ID = %d",
					$parent_id
				)
			);
			if ( ! $parent || $parent->post_name !== $segments[ $i ] ) {
				$matched = false;
				break;
			}
			$parent_id = (int) $parent->post_parent;
		}

		// The top-most matched segment must be a root post.
		if ( $matched && $parent_id === 0 ) {
			return (int) $candidate->ID;
		}
	}

	return 0;
}
