function wpbp_q_hide_category_from_main_query( $query ) {
    if ( is_admin() || ! $query->is_main_query() ) {
        return;
    }

    $exclude = array(
        'taxonomy'         => 'category',
        'field'            => 'slug',
        'terms'            => array( 'wpbp-q-hidden' ),
        'operator'         => 'NOT IN',
        'include_children' => false,
    );

    $existing = $query->get( 'tax_query' );

    if ( ! empty( $existing ) && is_array( $existing ) ) {
        $tax_query = array(
            'relation' => 'AND',
            $existing,
            $exclude,
        );
    } else {
        $tax_query = array( $exclude );
    }

    $query->set( 'tax_query', $tax_query );
}
