	/**
	 * Count posts of a post type that are in a given status (built-in or custom).
	 *
	 * @param string $post_type   Post type slug.
	 * @param string $post_status Post status slug (e.g. 'publish', 'wpbp_q_archived').
	 * @return int Number of matching posts, 0 if none.
	 */
	function wpbp_queries_019( string $post_type, string $post_status ): int {
		global $wpdb;

		if ( '' === $post_type || '' === $post_status ) {
			return 0;
		}

		$count = $wpdb->get_var(
			$wpdb->prepare(
				"SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type = %s AND post_status = %s",
				$post_type,
				$post_status
			)
		);

		return $count ? (int) $count : 0;
	}
}
