if ( ! function_exists( 'wpbp_rest_api_005' ) ) {
	/**
	 * Normalize a WP_Error into a REST response array with code, message, and status.
	 *
	 * @param WP_Error $error The error to normalize.
	 * @return array{code: string, message: string, status: int}
	 */
	function wpbp_rest_api_005( WP_Error $error ): array {
		$response = rest_convert_error_to_response( $error );

		$data   = (array) $response->get_data();
		$status = (int) $response->get_status();

		$code    = isset( $data['code'] ) ? $data['code'] : $error->get_error_code();
		$message = isset( $data['message'] ) ? $data['message'] : $error->get_error_message();

		return array(
			'code'    => (string) $code,
			'message' => (string) $message,
			'status'  => $status,
		);
	}
}
