/**
 * Item schema for a venue. Each property declares the contexts it belongs to.
 */
function wpbp_get_venue_schema() {
	return array(
		'$schema'    => 'http://json-schema.org/draft-04/schema#',
		'title'      => 'wpbp-venue',
		'type'       => 'object',
		'properties' => array(
			'name'        => array(
				'description' => 'Name of the venue.',
				'type'        => 'string',
				'context'     => array( 'view', 'edit' ),
				'readonly'    => true,
			),
			'capacity'    => array(
				'description' => 'Maximum capacity of the venue.',
				'type'        => 'integer',
				'context'     => array( 'view', 'edit' ),
				'readonly'    => true,
			),
			'owner_email' => array(
				'description' => 'Private contact email of the venue owner.',
				'type'        => 'string',
				'format'      => 'email',
				'context'     => array( 'edit' ),
				'readonly'    => true,
			),
		),
	);
}

/**
 * Permission check: edit context requires the edit_posts capability.
 */
function wpbp_venues_permissions_check( WP_REST_Request $request ) {
	$context = $request->get_param( 'context' );

	if ( 'edit' === $context && ! current_user_can( 'edit_posts' ) ) {
		return new WP_Error(
			'rest_forbidden_context',
			__( 'Sorry, you are not allowed to view venues in the edit context.' ),
			array( 'status' => 403 )
		);
	}

	return true;
}

/**
 * Build the response, letting WordPress strip fields by context via the schema.
 */
function wpbp_get_venues( WP_REST_Request $request ) {
	$context = $request->get_param( 'context' );
	if ( ! in_array( $context, array( 'view', 'edit' ), true ) ) {
		$context = 'view';
	}

	$schema  = wpbp_get_venue_schema();
	$venues  = get_option( 'wpbp_venues', array() );
	$items   = array();

	if ( ! is_array( $venues ) ) {
		$venues = array();
	}

	foreach ( $venues as $venue ) {
		if ( is_object( $venue ) ) {
			$venue = (array) $venue;
		}
		if ( ! is_array( $venue ) ) {
			continue;
		}

		$item = array(
			'name'        => isset( $venue['name'] ) ? (string) $venue['name'] : '',
			'capacity'    => isset( $venue['capacity'] ) ? (int) $venue['capacity'] : 0,
			'owner_email' => isset( $venue['owner_email'] ) ? (string) $venue['owner_email'] : '',
		);

		$items[] = rest_filter_response_by_context( $item, $schema, $context );
	}

	return rest_ensure_response( $items );
}

add_action(
	'rest_api_init',
	function () {
		register_rest_route(
			'wpbp/v1',
			'/venues',
			array(
				array(
					'methods'             => WP_REST_Server::READABLE,
					'callback'            => 'wpbp_get_venues',
					'permission_callback' => 'wpbp_venues_permissions_check',
					'args'                => array(
						'context' => array(
							'description'       => 'Scope under which the request is made; determines fields present in response.',
							'type'              => 'string',
							'enum'              => array( 'view', 'edit' ),
							'default'           => 'view',
							'sanitize_callback' => 'sanitize_key',
							'validate_callback' => 'rest_validate_request_arg',
						),
					),
				),
				'schema' => 'wpbp_get_venue_schema',
			)
		);
	}
);
