function wpbp_register_notes_route() {
    register_rest_route(
        'wpbp/v1',
        '/notes/(?P<id>\d+)',
        array(
            'methods'             => WP_REST_Server::READABLE,
            'callback'            => 'wpbp_get_note',
            'permission_callback' => '__return_true',
            'args'                => array(
                'id' => array(
                    'description'       => 'Note ID.',
                    'type'              => 'integer',
                    'validate_callback' => function ( $value ) {
                        return is_numeric( $value );
                    },
                    'sanitize_callback' => 'absint',
                ),
            ),
        )
    );
}

function wpbp_get_note( WP_REST_Request $request ) {
    $id    = absint( $request['id'] );
    $notes = get_option( 'wpbp_notes', array() );

    if ( ! is_array( $notes ) || ! isset( $notes[ $id ] ) || ! is_array( $notes[ $id ] ) ) {
        return new WP_Error(
            'wpbp_note_not_found',
            __( 'Note not found.', 'wpbp' ),
            array( 'status' => 404 )
        );
    }

    $note   = $notes[ $id ];
    $title  = isset( $note['title'] ) ? $note['title'] : '';
    $author = isset( $note['author'] ) ? absint( $note['author'] ) : 0;

    $response = new WP_REST_Response(
        array(
            'id'     => $id,
            'title'  => $title,
            'author' => $author,
        )
    );

    // Self link: not embeddable.
    $response->add_link( 'self', rest_url( 'wpbp/v1/notes/' . $id ) );

    // Author link: the only embeddable relation.
    if ( $author ) {
        $response->add_link(
            'author',
            rest_url( 'wp/v2/users/' . $author ),
            array( 'embeddable' => true )
        );
    }

    return $response;
}

if ( did_action( 'rest_api_init' ) ) {
    wpbp_register_notes_route();
} else {
    add_action( 'rest_api_init', 'wpbp_register_notes_route' );
}
