<?php

function wpbp_register_booking_route() {
    register_rest_route( 'wpbp/v1', '/bookings', array(
        'methods'             => WP_REST_Server::CREATABLE,
        'callback'            => 'wpbp_handle_booking',
        'permission_callback' => '__return_true',
        'args'                => array(
            'room'   => array(
                'type'     => 'string',
                'required' => true,
                'enum'     => array( 'harbor', 'cedar' ),
            ),
            'guests' => array(
                'type'    => 'integer',
                'minimum' => 1,
                'default' => 2,
            ),
        ),
    ) );
}

function wpbp_handle_booking( WP_REST_Request $request ) {
    $room   = $request->get_param( 'room' );
    $guests = (int) $request->get_param( 'guests' );

    $booked = get_option( 'wpbp_bookings', array() );
    if ( ! is_array( $booked ) ) {
        $booked = array();
    }

    $problems = array();

    if ( in_array( $room, $booked, true ) ) {
        $problems['wpbp_room_taken'] = __( 'This room has already been booked.', 'wpbp' );
    }

    if ( $guests > 4 ) {
        $problems['wpbp_over_capacity'] = __( 'A room cannot hold more than 4 guests.', 'wpbp' );
    }

    if ( ! empty( $problems ) ) {
        $status = isset( $problems['wpbp_room_taken'] ) ? 409 : 400;
        $error  = new WP_Error();
        foreach ( $problems as $code => $message ) {
            $error->add( $code, $message, array( 'status' => $status ) );
        }
        return $error;
    }

    $booked[] = $room;
    update_option( 'wpbp_bookings', $booked );

    $response = new WP_REST_Response(
        array(
            'room'   => $room,
            'guests' => $guests,
        ),
        201
    );

    return $response;
}

if ( did_action( 'rest_api_init' ) ) {
    wpbp_register_booking_route();
} else {
    add_action( 'rest_api_init', 'wpbp_register_booking_route' );
}
