<?php

if ( ! function_exists( 'wpbp_register_report_route' ) ) {

	function wpbp_register_report_route() {
		register_rest_route(
			'wpbp/v1',
			'/reports/(?P<id>\d+)',
			array(
				'methods'             => WP_REST_Server::READABLE,
				'callback'            => 'wpbp_rest_get_report',
				'permission_callback' => '__return_true',
				'args'                => array(
					'id' => array(
						'description'       => 'Report ID.',
						'type'              => 'integer',
						'required'          => true,
						'validate_callback' => function ( $value ) {
							return is_numeric( $value );
						},
						'sanitize_callback' => 'absint',
					),
				),
			)
		);
	}

	function wpbp_rest_get_report( WP_REST_Request $request ) {
		$report_id = (int) $request['id'];
		$reports   = get_option( 'wpbp_reports', array() );

		if ( ! is_array( $reports ) || ! array_key_exists( $report_id, $reports ) ) {
			return new WP_Error(
				'wpbp_report_not_found',
				__( 'Report not found.', 'wpbp' ),
				array( 'status' => 404 )
			);
		}

		$requested = $request->get_param( '_fields' );
		$fields    = array();

		if ( null !== $requested && '' !== $requested ) {
			foreach ( wp_parse_list( $requested ) as $field ) {
				$field = trim( (string) $field );
				if ( '' === $field ) {
					continue;
				}
				// Support nested notation like "stats.total" by using the top-level key.
				$parts    = explode( '.', $field );
				$fields[] = $parts[0];
			}
			$fields = array_unique( $fields );
		}

		$all = empty( $fields );

		$data = array();

		if ( $all || in_array( 'id', $fields, true ) ) {
			$data['id'] = $report_id;
		}

		if ( $all || in_array( 'title', $fields, true ) ) {
			$data['title'] = $reports[ $report_id ];
		}

		if ( $all || in_array( 'stats', $fields, true ) ) {
			$data['stats'] = wpbp_report_stats( $report_id );
		}

		return rest_ensure_response( $data );
	}
}

if ( did_action( 'rest_api_init' ) ) {
	wpbp_register_report_route();
} else {
	add_action( 'rest_api_init', 'wpbp_register_report_route' );
}
