function wpbp_maintenance_gate( $result, $server, $request ) {
    if ( '1' !== (string) get_option( 'wpbp_maintenance' ) ) {
        return $result;
    }

    $route = '/' . ltrim( (string) $request->get_route(), '/' );

    // Matches /wpbp/v1 (the namespace index) and anything beneath it, but not e.g. /wpbp/v10.
    if ( ! preg_match( '#^/wpbp/v1(?:/|$)#', $route ) ) {
        return $result;
    }

    return new WP_Error(
        'wpbp_maintenance',
        __( 'The API is currently down for maintenance. Please try again later.', 'wpbp' ),
        array( 'status' => 503 )
    );
}
