<?php

function wpbp_rest_authenticate_key( $result ) {
    // Another authentication method has already produced a result.
    if ( null !== $result ) {
        return $result;
    }

    // Header missing: leave the request exactly as found.
    if ( ! isset( $_SERVER['HTTP_X_WPBP_KEY'] ) ) {
        return $result;
    }

    $provided = wp_unslash( $_SERVER['HTTP_X_WPBP_KEY'] );
    if ( is_array( $provided ) ) {
        $provided = '';
    }
    $provided = (string) $provided;

    $expected = get_option( 'wpbp_api_key' );
    $expected = is_scalar( $expected ) ? (string) $expected : '';

    if ( '' === $expected || ! hash_equals( $expected, $provided ) ) {
        return new WP_Error(
            'wpbp_bad_key',
            __( 'Invalid API key.', 'wpbp' ),
            array( 'status' => 401 )
        );
    }

    $user_id = absint( get_option( 'wpbp_api_user' ) );
    $user    = $user_id ? get_userdata( $user_id ) : false;

    if ( ! $user ) {
        return new WP_Error(
            'wpbp_bad_user',
            __( 'The API user is not configured correctly.', 'wpbp' ),
            array( 'status' => 401 )
        );
    }

    wp_set_current_user( $user->ID );

    return true;
}

add_filter( 'rest_authentication_errors', 'wpbp_rest_authenticate_key' );
