/**
 * Registers item URLs as items/<item-slug> using the %wpbp_item% placeholder.
 *
 * Rewrite rules are NOT flushed here. Flush once on plugin/theme activation
 * or deactivation, or by visiting Settings > Permalinks.
 */
function wpbp_rewrite_permalinks_001(): void {
    global $wp, $wp_rewrite;

    static $registered = false;
    if ( $registered ) {
        return;
    }
    $registered = true;

    // Rewrite tag: also makes WordPress aware of the wpbp_item query var.
    add_rewrite_tag( '%wpbp_item%', '([^/]+)', 'wpbp_item=' );

    // Register the query var on the already-initialised WP object.
    if ( isset( $wp ) && $wp instanceof WP ) {
        $wp->add_query_var( 'wpbp_item' );
    }

    // Also register through the filter for any later request parsing.
    add_filter(
        'query_vars',
        static function ( array $vars ): array {
            if ( ! in_array( 'wpbp_item', $vars, true ) ) {
                $vars[] = 'wpbp_item';
            }
            return $vars;
        }
    );

    // Extra permalink structure: items/<item-slug>
    add_permastruct(
        'wpbp_item',
        'items/%wpbp_item%',
        array(
            'with_front'  => false,
            'ep_mask'     => EP_NONE,
            'paged'       => false,
            'feed'        => false,
            'forcomments' => false,
            'walk_dirs'   => false,
            'endpoints'   => false,
        )
    );
}

