function wpbp_roles_caps_001(): bool {
    $role_name    = 'wpbp_manager';
    $display_name = 'WPBP Manager';
    $caps         = array(
        'read'         => true,
        'wpbp_manage'  => true,
    );

    // Ensure a clean registration with the expected capabilities.
    $existing = get_role( $role_name );
    if ( $existing instanceof WP_Role ) {
        foreach ( $caps as $cap => $grant ) {
            if ( ! $existing->has_cap( $cap ) ) {
                $existing->add_cap( $cap, $grant );
            }
        }
    } else {
        $added = add_role( $role_name, $display_name, $caps );
        if ( ! ( $added instanceof WP_Role ) ) {
            return false;
        }
    }

    $role = get_role( $role_name );

    if ( ! ( $role instanceof WP_Role ) ) {
        return false;
    }

    return $role->has_cap( 'wpbp_manage' ) && $role->has_cap( 'read' );
}
