function wpbp_roles_caps_009( string $capability ): array {
	global $wpdb;

	if ( '' === $capability ) {
		return array();
	}

	$candidates = array();

	// Users whose role includes the capability.
	$roles_with_cap = array();
	foreach ( wp_roles()->roles as $role_name => $role_info ) {
		if ( ! empty( $role_info['capabilities'][ $capability ] ) ) {
			$roles_with_cap[] = $role_name;
		}
	}

	if ( ! empty( $roles_with_cap ) ) {
		$role_users = get_users(
			array(
				'role__in' => $roles_with_cap,
				'fields'   => 'ID',
			)
		);
		foreach ( $role_users as $id ) {
			$candidates[ (int) $id ] = true;
		}
	}

	// Users with the capability granted directly.
	$direct_users = get_users(
		array(
			'fields'     => 'ID',
			'meta_query' => array(
				array(
					'key'     => $wpdb->get_blog_prefix() . 'capabilities',
					'value'   => '"' . $capability . '";b:1',
					'compare' => 'LIKE',
				),
			),
		)
	);
	foreach ( $direct_users as $id ) {
		$candidates[ (int) $id ] = true;
	}

	// Verify the final effective state (explicit denials override role grants).
	$result = array();
	foreach ( array_keys( $candidates ) as $id ) {
		$user = get_userdata( $id );
		if ( $user && ! empty( $user->allcaps[ $capability ] ) ) {
			$result[] = (int) $id;
		}
	}

	sort( $result );

	return $result;
}
