function wpbp_security_001( string $html, string $href ): string {
	$processor = new WP_HTML_Tag_Processor( $html );

	if ( ! $processor->next_tag( 'a' ) ) {
		return $html;
	}

	// Sanitize the URL: strips dangerous protocols such as javascript:, and invalid characters.
	$safe_href = esc_url_raw( trim( $href ) );

	if ( '' === $safe_href ) {
		// Unsafe or empty URL: do not leave a dangerous or misleading href in place.
		$processor->remove_attribute( 'href' );
	} else {
		// set_attribute() handles proper attribute-value escaping.
		$processor->set_attribute( 'href', $safe_href );
	}

	return $processor->get_updated_html();
}
```

