	// Sanitize the URL: strips dangerous protocols such as javascript:, and invalid characters.
	$safe_href = esc_url_raw( trim( $href ) );

	if ( '' === $safe_href ) {
		// Unsafe or empty URL: do not leave a dangerous or misleading href in place.
		$processor->remove_attribute( 'href' );
	} else {
