function wpbp_security_005( string $url ): string {
	$url = trim( $url );

	if ( '' === $url ) {
		return '';
	}

	/*
	 * esc_url() prepends "http://" when a URL has no scheme (and isn't
	 * relative, an anchor, a query string, or a bare .php file). To prefer
	 * HTTPS, add the scheme ourselves under the same conditions.
	 */
	if (
		false === strpos( $url, ':' )
		&& ! in_array( $url[0], array( '/', '#', '?' ), true )
		&& ! preg_match( '/^[a-z0-9-]+?\.php/i', $url )
	) {
		$url = 'https://' . $url;
	}

	return esc_url( $url, array( 'https', 'http' ) );
}
