	/**
	 * Process a site tagline submitted via a form.
	 *
	 * @param string $submitted Tagline as received (slashed by WordPress).
	 * @return string Markup snippet.
	 */
	function wpbp_security_011( string $submitted ): string {
		// Remove slashes added by WordPress first.
		$unslashed = wp_unslash( $submitted );

		// Clean to single-line text with no HTML markup.
		$clean = sanitize_text_field( $unslashed );

		// Store the cleaned value.
		update_option( 'wpbp_tagline', $clean );

		// Context-specific escaping.
		$attr_value = esc_attr( $clean );
		$js_value   = esc_js( $clean );

		$output  = '<span title="' . $attr_value . '">' . "\n";
		$output .= '<script>' . "\n";
		$output .= "var wpbpTagline = '" . $js_value . "';\n";
		$output .= '</script>' . "\n";
		$output .= '</span>';

		return $output;
	}
}
