function wpbp_settings_options_006( string $code ) {
    static $memo = array();

    if ( array_key_exists( $code, $memo ) ) {
        return $memo[ $code ];
    }

    $key    = 'wpbp_stock_' . $code;
    $cached = get_transient( $key );

    // Values are wrapped in an array so that false and null (valid answers)
    // can be told apart from a cache miss (get_transient returns false).
    if ( is_array( $cached ) && array_key_exists( 'v', $cached ) ) {
        $memo[ $code ] = $cached['v'];
        return $cached['v'];
    }

    $result = wpbp_stock_lookup_source( $code );

    if ( $result !== true && $result !== false ) {
        $result = null;
    }

    set_transient( $key, array( 'v' => $result ), 5 * MINUTE_IN_SECONDS );
    $memo[ $code ] = $result;

    return $result;
}
