function wpbp_settings_options_007( array $autoload_map ): array {
	global $wpdb;

	$result = array();
	$wanted = array();

	foreach ( $autoload_map as $name => $flag ) {
		$name            = (string) $name;
		$wanted[ $name ] = (bool) $flag;
		$result[ $name ] = false;
	}

	if ( empty( $wanted ) ) {
		return $result;
	}

	// Values considered "autoloading".
	if ( function_exists( 'wp_autoload_values_to_autoload' ) ) {
		$autoload_values = wp_autoload_values_to_autoload();
		$on_value        = 'on';
		$off_value       = 'off';
	} else {
		$autoload_values = array( 'yes', 'on', 'auto-on', 'auto' );
		$on_value        = 'yes';
		$off_value       = 'no';
	}

	$names        = array_keys( $wanted );
	$placeholders = implode( ',', array_fill( 0, count( $names ), '%s' ) );

	// Query 1: fetch current stored values in one go.
	// phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared
	$rows = $wpdb->get_results(
		$wpdb->prepare(
			"SELECT option_name, autoload FROM {$wpdb->options} WHERE option_name IN ($placeholders)",
			$names
		)
	);

	$to_on  = array();
	$to_off = array();

	if ( $rows ) {
		foreach ( $rows as $row ) {
			$name = (string) $row->option_name;
			if ( ! isset( $wanted[ $name ] ) ) {
				continue;
			}
			$is_on = in_array( $row->autoload, $autoload_values, true );
			if ( $wanted[ $name ] && ! $is_on ) {
				$to_on[] = $name;
			} elseif ( ! $wanted[ $name ] && $is_on ) {
				$to_off[] = $name;
			}
		}
	}

	$changed = array();

	// Query 2: bulk switch on.
	if ( $to_on ) {
		$ph = implode( ',', array_fill( 0, count( $to_on ), '%s' ) );
		// phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared
		$affected = $wpdb->query(
			$wpdb->prepare(
				"UPDATE {$wpdb->options} SET autoload = %s WHERE option_name IN ($ph)",
				array_merge( array( $on_value ), $to_on )
			)
		);
		if ( false !== $affected ) {
			foreach ( $to_on as $name ) {
				$result[ $name ] = true;
				$changed[]       = $name;
			}
		}
	}

	// Query 3: bulk switch off.
	if ( $to_off ) {
		$ph = implode( ',', array_fill( 0, count( $to_off ), '%s' ) );
		// phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared
		$affected = $wpdb->query(
			$wpdb->prepare(
				"UPDATE {$wpdb->options} SET autoload = %s WHERE option_name IN ($ph)",
				array_merge( array( $off_value ), $to_off )
			)
		);
		if ( false !== $affected ) {
			foreach ( $to_off as $name ) {
				$result[ $name ] = true;
				$changed[]       = $name;
			}
		}
	}

	// Invalidate caches so autoload lists reflect the change.
	if ( $changed ) {
		foreach ( $changed as $name ) {
			wp_cache_delete( $name, 'options' );
		}
		wp_cache_delete( 'alloptions', 'options' );
	}

	return $result;
}
