		$result[ $name ] = false;
	}

	// Single query for the whole list.
	$placeholders = implode( ', ', array_fill( 0, count( $names ), '%s' ) );
	$sql          = $wpdb->prepare(
		"SELECT option_name, option_value FROM {$wpdb->options} WHERE option_name IN ($placeholders)",
		$names
	);
