	if ( is_array( $rows ) ) {
		foreach ( $rows as $row ) {
			$value = maybe_unserialize( $row->option_value );
			/** This filter is documented in wp-includes/option.php */
			$value = apply_filters( "option_{$row->option_name}", $value, $row->option_name );
			$result[ $row->option_name ] = $value;
