/**
 * Report whether the supplied content contains the supplied registered shortcode tag,
 * including shortcodes nested inside the content of other shortcodes.
 * The shortcode is never rendered.
 *
 * @param string $content Content to inspect.
 * @param string $tag     Shortcode tag to look for.
 * @return bool True if the registered shortcode tag is present, false otherwise.
 */
function wpbp_shortcodes_004( string $content, string $tag ): bool {
	if ( '' === $content || '' === $tag ) {
		return false;
	}

	// The tag must be a registered shortcode.
	if ( ! shortcode_exists( $tag ) ) {
		return false;
	}

	// Quick bail-out: no opening bracket means no shortcodes.
	if ( false === strpos( $content, '[' ) ) {
		return false;
	}

	// has_shortcode() parses the content with the Shortcode API regex
	// and recurses into enclosed (nested) shortcode content, without rendering.
	return (bool) has_shortcode( $content, $tag );
}
