if ( ! function_exists( 'brand_tokens_add_theme_json_settings' ) ) {
    /**
     * Add brand design tokens to the global settings (theme.json data layer).
     * WordPress will emit them as:
     *   --wp--custom--brand-color--primary
     *   --wp--custom--brand-spacing--gutter
     *
     * @param WP_Theme_JSON_Data $theme_json Existing theme data.
     * @return WP_Theme_JSON_Data
     */
    function brand_tokens_add_theme_json_settings( $theme_json ) {
        $version = defined( 'WP_Theme_JSON::LATEST_SCHEMA' ) ? WP_Theme_JSON::LATEST_SCHEMA : 2;

        $tokens = array(
            'version'  => $version,
            'settings' => array(
                'custom' => array(
                    'brandColor'   => array(
                        'primary' => '#0abc12',
                    ),
                    'brandSpacing' => array(
                        'gutter' => '2.5rem',
                    ),
                ),
            ),
        );

        // update_with() merges into existing data, so the theme's own variables are preserved.
        return $theme_json->update_with( $tokens );
    }
}

// Attach directly (boot actions have already fired).
