function wpbp_insert_promo_after_second_block( $content ) {
	if ( ! is_string( $content ) || '' === $content || ! has_blocks( $content ) ) {
		return $content;
	}

	$blocks = parse_blocks( $content );

	// Locate real top-level blocks (ignore freeform/whitespace chunks with null blockName).
	$real_count   = 0;
	$second_index = null;
	foreach ( $blocks as $index => $block ) {
		if ( ! empty( $block['blockName'] ) ) {
			$real_count++;
			if ( 2 === $real_count ) {
				$second_index = $index;
			}
		}
	}

	if ( $real_count <= 2 || null === $second_index ) {
		return $content;
	}

	$html  = '<p class="wpbp-promo">Sponsored by WPBP</p>';
	$promo = array(
		'blockName'    => 'core/paragraph',
		'attrs'        => array( 'className' => 'wpbp-promo' ),
		'innerBlocks'  => array(),
		'innerHTML'    => $html,
		'innerContent' => array( $html ),
	);

	array_splice( $blocks, $second_index + 1, 0, array( $promo ) );

	return serialize_blocks( $blocks );
}
