class WPBP_Recent_Items_Widget extends WP_Widget {

	public function __construct() {
		parent::__construct(
			'wpbp-recent-items',
			__( 'Recent Items', 'wpbp' ),
			array(
				'classname'   => 'wpbp-recent-items',
				'description' => __( 'Lists the most recent published entries.', 'wpbp' ),
			)
		);
	}

	public function widget( $args, $instance ) {
		$args = wp_parse_args(
			$args,
			array(
				'before_widget' => '',
				'after_widget'  => '',
				'before_title'  => '',
				'after_title'   => '',
			)
		);

		$post_type = ( isset( $instance['post_type'] ) && '' !== $instance['post_type'] ) ? $instance['post_type'] : 'post';
		$number    = isset( $instance['number'] ) ? absint( $instance['number'] ) : 3;

		echo $args['before_widget'];

		if ( ! empty( $instance['title'] ) ) {
			$title = apply_filters( 'widget_title', $instance['title'], $instance, $this->id_base );
			echo $args['before_title'] . $title . $args['after_title'];
		}

		$items = array();
		if ( $number > 0 ) {
			$items = get_posts(
				array(
					'post_type'           => $post_type,
					'post_status'         => 'publish',
					'posts_per_page'      => $number,
					'orderby'             => 'date',
					'order'               => 'DESC',
					'no_found_rows'       => true,
					'ignore_sticky_posts' => true,
				)
			);
		}

		echo '<ul>';
		foreach ( $items as $item ) {
			printf(
				'<li><a href="%s">%s</a></li>',
				esc_url( get_permalink( $item ) ),
				esc_html( get_the_title( $item ) )
			);
		}
		echo '</ul>';

		echo $args['after_widget'];
	}

	public function form( $instance ) {
		$title     = isset( $instance['title'] ) ? $instance['title'] : '';
		$post_type = isset( $instance['post_type'] ) ? $instance['post_type'] : 'post';
		$number    = isset( $instance['number'] ) ? absint( $instance['number'] ) : 3;
		?>
		<p>
			<label for="<?php echo esc_attr( $this->get_field_id( 'title' ) ); ?>"><?php esc_html_e( 'Title:', 'wpbp' ); ?></label>
			<input class="widefat" id="<?php echo esc_attr( $this->get_field_id( 'title' ) ); ?>" name="<?php echo esc_attr( $this->get_field_name( 'title' ) ); ?>" type="text" value="<?php echo esc_attr( $title ); ?>">
		</p>
		<p>
			<label for="<?php echo esc_attr( $this->get_field_id( 'post_type' ) ); ?>"><?php esc_html_e( 'Content type:', 'wpbp' ); ?></label>
			<input class="widefat" id="<?php echo esc_attr( $this->get_field_id( 'post_type' ) ); ?>" name="<?php echo esc_attr( $this->get_field_name( 'post_type' ) ); ?>" type="text" value="<?php echo esc_attr( $post_type ); ?>">
		</p>
		<p>
			<label for="<?php echo esc_attr( $this->get_field_id( 'number' ) ); ?>"><?php esc_html_e( 'Number of entries:', 'wpbp' ); ?></label>
			<input class="tiny-text" id="<?php echo esc_attr( $this->get_field_id( 'number' ) ); ?>" name="<?php echo esc_attr( $this->get_field_name( 'number' ) ); ?>" type="number" min="1" step="1" value="<?php echo esc_attr( $number ); ?>">
		</p>
		<?php
	}

	public function update( $new_instance, $old_instance ) {
		$instance              = array();
		$instance['title']     = isset( $new_instance['title'] ) ? sanitize_text_field( $new_instance['title'] ) : '';
		$instance['post_type'] = ! empty( $new_instance['post_type'] ) ? sanitize_key( $new_instance['post_type'] ) : 'post';
		$instance['number']    = isset( $new_instance['number'] ) ? max( 1, absint( $new_instance['number'] ) ) : 3;
		return $instance;
	}
}

